CREATE TABLE IF NOT EXISTS business_hours(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),barber_id uuid NOT NULL REFERENCES barbers(id) ON DELETE CASCADE,weekday smallint NOT NULL CHECK(weekday BETWEEN 0 AND 6),starts_at time NOT NULL,ends_at time NOT NULL,active boolean NOT NULL DEFAULT true,CHECK(ends_at>starts_at),UNIQUE(barber_id,weekday,starts_at));
CREATE TABLE IF NOT EXISTS schedule_blocks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),barber_id uuid REFERENCES barbers(id) ON DELETE CASCADE,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,reason varchar(200),created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at));
CREATE TABLE IF NOT EXISTS message_queue(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),appointment_id uuid NOT NULL REFERENCES appointments(id) ON DELETE CASCADE,event varchar(30) NOT NULL CHECK(event IN ('CONFIRMATION','REMINDER','CANCELLATION')),channel varchar(20) NOT NULL DEFAULT 'WHATSAPP',recipient varchar(40) NOT NULL,payload jsonb NOT NULL,status varchar(20) NOT NULL DEFAULT 'PENDING',scheduled_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz,attempts integer NOT NULL DEFAULT 0,last_error text,created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO business_hours(barber_id,weekday,starts_at,ends_at) SELECT b.id,d,'09:00','18:00' FROM barbers b CROSS JOIN generate_series(1,6) d WHERE NOT EXISTS(SELECT 1 FROM business_hours) ON CONFLICT DO NOTHING;
